
import unittest

import PARAMETERS as CON
import PARAMETERS as param
from deuterium_calculator import get_ppm


# copy of the previous implementation.
# here to use as a comparison for alternative implementations.

# Takes in a list of tuples and combines each where first elements is within a ppm tolerance
# This is used to combine peaks of the exact same mz in consecutive nearby scans.
def tuple_combine(some_list):
    
    changed = True
    just_changed = False
    start_list = sorted(some_list, key=lambda x: x[0])
    new_list = []
    
    # [(m/z, intensity, count) ... ]
    begin_list = [(start[0], start[1], 1) for start in start_list]
    start_list = begin_list

    while changed and len(start_list) != 0:
        changed = False
        for i in range(len(start_list) - 1):
            if just_changed:
                just_changed = False
                continue
            ppm = abs(get_ppm(start_list[i][0], start_list[i+1][0]))
            if ppm < CON.SLIDING_WINDOW_PPM_TOLERANCE:
                count1 = start_list[i][2]
                count2 = start_list[i + 1][2]
                mz1 = start_list[i][0] * count1
                mz2 = start_list[i + 1][0] * count2
                count = count1 + count2
                mz = (mz1 + mz2) / count
                intensity = start_list[i][1] + start_list[i + 1][1]
                new_list.append((mz, intensity, count))
                changed = True
                just_changed = True
            else:
                new_list.append(start_list[i])
        if not just_changed:
            new_list.append(start_list[len(start_list) - 1])
        start_list = new_list
        new_list = []
        just_changed = False
    return start_list


def _is_tuple_before(t1, t2):
    return t1[0] <= t2[0]

def _should_tuples_merge_ppm(t1, t2):
    ppm = abs(get_ppm(t1[0], t2[0]))
    return ppm < param.SLIDING_WINDOW_PPM_TOLERANCE

def _merge_tuples_ppm(prev, curr):
    count1 = prev[2]
    count2 = curr[2]
    mz1 = prev[0] * count1
    mz2 = curr[0] * count2
    intensity1 = prev[1]
    intensity2 = curr[1]
    count = count1 + count2
    mz = (mz1 + mz2) / count
    intensity = intensity1 + intensity2
    return (mz, intensity, count)

# adjustment of mergesort algorithm to merge elements within ppm tolerance
def tuple_merge(tuple_list):
    duplicate_list = [(t[0], t[1], 1) for t in tuple_list]
    _tuple_mergesort(duplicate_list)
    
    return duplicate_list

def _tuple_mergesort(tuple_list: list) -> list:
    if len(tuple_list) <= 1:
        return tuple_list
    
    mid = len(tuple_list) // 2
    left_sub = tuple_list[:mid]
    right_sub = tuple_list[mid:]
    
    left_sorted = _tuple_mergesort(left_sub)
    right_sorted = _tuple_mergesort(right_sub)
    
    return _tuple_merger(left_sorted, right_sorted)
    
def _tuple_merger(left: list, right: list):
    i = 0
    j = 0
    out = []
    
    while i < len(left) and j < len(right):
        if _is_tuple_before(left[i], right[j]):
            out.append(left[i])
            i += 1
        else:
            out.append(right[j])
            j += 1
        
        if len(out) > 1:
            curr = out[-1]
            prev = out[-2]
            if _should_tuples_merge_ppm(curr, prev):
                out.pop()
                out.pop()
                ppm_tuple = _merge_tuples_ppm(prev, curr)
                out.append(ppm_tuple)
    
    while i < len(left):
        out.append(left[i])
        i += 1
        if len(out) > 1:
            curr = out[-1]
            prev = out[-2]
            if _should_tuples_merge_ppm(curr, prev):
                out.pop()
                out.pop()
                ppm_tuple = _merge_tuples_ppm(prev, curr)
                out.append(ppm_tuple)
    
    while j < len(right):
        out.append(right[j])
        j+= 1
        if len(out) > 1:
            curr = out[-1]
            prev = out[-2]
            if _should_tuples_merge_ppm(curr, prev):
                out.pop()
                out.pop()
                ppm_tuple = _merge_tuples_ppm(prev, curr)
                out.append(ppm_tuple)
    
    return out
    
 

