class TestTupleCombinations(unittest.TestCase):
    
    def test_same_outputs(self):
        naive = tuple_combine(EX_DATA)
        merger = tuple_merge(EX_DATA)
        self.assertEqual(naive, merger)
        
    def test_mergesorting(self):
        good_sorted = sorted(EX_DATA, key = lambda x : x[0])
        merge_sorted = tuple_merge(EX_DATA)
        self.assertEqual(good_sorted, merge_sorted)
    

if __name__ == '__main__':
    unittest.main()